class Solution {
public:
    int minMutation(string startGene, string endGene, vector<string>& bank) {
        unordered_set<string> bankSet(bank.begin(), bank.end());
        if (!bankSet.count(endGene)) return -1;
        queue<pair<string, int>> q;
        q.push({startGene, 0});
        unordered_set<string> visited;
        visited.insert(startGene);
        const string nuc = "ACGT";
        while (!q.empty()) {
            auto [curr, step] = q.front();
            q.pop();
            if (curr == endGene) return step;
            for (size_t i = 0; i < curr.size(); ++i) {
                char orig = curr[i];
                for (char c : nuc) {
                    if (c == orig) continue;
                    curr[i] = c;
                    if (bankSet.count(curr) && !visited.count(curr)) {
                        visited.insert(curr);
                        q.push({curr, step + 1});
                    }
                }
                curr[i] = orig;
            }
        }
        return -1;
    }
};

class Solution {
    public int minMutation(String startGene, String endGene, String[] bank) {
        Set<String> bankSet = new HashSet<>(Arrays.asList(bank));
        if (!bankSet.contains(endGene)) return -1;
        Queue<Pair> q = new LinkedList<>();
        q.offer(new Pair(startGene, 0));
        Set<String> visited = new HashSet<>();
        visited.add(startGene);
        char[] nuc = {'A', 'C', 'G', 'T'};
        while (!q.isEmpty()) {
            Pair cur = q.poll();
            if (cur.gene.equals(endGene)) return cur.step;
            char[] arr = cur.gene.toCharArray();
            for (int i = 0; i < arr.length; i++) {
                char orig = arr[i];
                for (char c : nuc) {
                    if (c == orig) continue;
                    arr[i] = c;
                    String next = new String(arr);
                    if (bankSet.contains(next) && !visited.contains(next)) {
                        visited.add(next);
                        q.offer(new Pair(next, cur.step + 1));
                    }
                }
                arr[i] = orig;
            }
        }
        return -1;
    }

    static class Pair {
        String gene;
        int step;
        Pair(String g, int s) { this.gene = g; this.step = s; }
    }
}

/**
 * @param {string} startGene
 * @param {string} endGene
 * @param {string[]} bank
 * @return {number}
 */
var minMutation = function(startGene, endGene, bank) {
    const bankSet = new Set(bank);
    if (!bankSet.has(endGene)) return -1;
    const q = [[startGene, 0]];
    const visited = new Set([startGene]);
    const nuc = ['A', 'C', 'G', 'T'];
    while (q.length > 0) {
        const [curr, step] = q.shift();
        if (curr === endGene) return step;
        for (let i = 0; i < curr.length; i++) {
            for (const c of nuc) {
                if (c === curr[i]) continue;
                const next = curr.slice(0, i) + c + curr.slice(i + 1);
                if (bankSet.has(next) && !visited.has(next)) {
                    visited.add(next);
                    q.push([next, step + 1]);
                }
            }
        }
    }
    return -1;
};
